# zt_bug 6962 回写序列（connection_name=新禅道，每步必带）

## 1) 查现状（拿 product/project/execution/openedBy）
mcp_gateway {
  "server": "dbx",
  "tool": "dbx_execute_query",
  "arguments": {
    "connection_name": "新禅道",
    "sql": "SELECT id,status,assignedTo,openedBy,product,project,execution,resolution FROM zt_bug WHERE id=6962;"
  }
}
核验: 记录 openedBy（回写 assignedTo 用）与 product/project/execution 原值

## 2) 开事务 session
mcp_gateway {
  "server": "dbx",
  "tool": "dbx_open_session",
  "arguments": {
    "connection_name": "新禅道",
    "enable_transactions": true
  }
}
核验: 取返回的 session_id，后续所有事务内调用都带它 + connection_name

## 3) begin
mcp_gateway {
  "server": "dbx",
  "tool": "dbx_begin_transaction",
  "arguments": {
    "connection_name": "新禅道",
    "session_id": "<session_id>"
  }
}
核验: 成功后再执行第 4/5 步

## 4) UPDATE zt_bug → resolved
mcp_gateway {
  "server": "dbx",
  "tool": "dbx_execute_query",
  "arguments": {
    "connection_name": "新禅道",
    "sql": "UPDATE zt_bug SET status='resolved', resolution='fixed', resolvedBuild='trunk', resolvedBy='tiany', resolvedDate=NOW(), assignedTo='<openedBy>', lastEditedBy='tiany', lastEditedDate=NOW() WHERE id=6962;",
    "session_id": "<session_id>"
  }
}
核验: affected rows = 1

